/// <summary>
/// Gets or sets the 
/// </summary>
/// <param name = "_partsTest">
/// <returns><c>mdfTable</c></returns>
public MetCustomerMdfTable parmMDFTable(MetCustomerMdfTable _mdfTable = mdfTable)
{
    mdfTable = _mdfTable;
    return mdfTable;
}

/// <summary>
/// Creates startup screen
/// </summary>
/// <returns>True if session is started</returns>
public boolean createForm()
{
    boolean         ret;
    Args            args = new Args();
    FormRun         METCustomerMDFSetup;

    MetCustomerMdfTable  currentRecord = this.parmMDFTable();

    args.name(formStr(METCustomerMDFSetup));
    args.caller(this);
    METCustomerMDFSetup = classfactory.formRunClass(args);
    METCustomerMDFSetup.init();
    METCustomerMDFSetup.run();
    METCustomerMDFSetup.wait();

    if (METCustomerMDFSetup.closedOk())
    {   
        ret = true;
    }
    else
    {
        this.parmMDFTable(currentRecord);
        ret = false;
    }
    return ret;
}

/// <summary>
/// Refreshes the calling form's datasource
/// </summary>
/// <returns>True if session is started</returns>
public static void getRefreshData(Args _args)
{

    Object calleform;
    FormDataSource fds;
    calleform = _args.caller();
    fds = _args.record().datasource();

    if(calleform)
    {
        fds.refresh();
        fds.research(true);
    }

}

