/// <summary>


/// <summary>
/// Creates the  startup screen
/// </summary>
/// <returns>True  session is started</returns>
public boolean createSetupForm()
{
    boolean         ret;
    Args            args = new Args();
    FormRun         METCustomerMDFSetupDetailsExtended;

    MetCustomerMdfSetupTable  currentRecord = this.parmMDFSetupTable();

    MetCustomerMdfTable  currentRecordParent = this.parmMDFTable();

    args.name(formStr(METCustomerMDFSetupDetailsExtended));
    args.caller(this);
    METCustomerMDFSetupDetailsExtended = classfactory.formRunClass(args);
    METCustomerMDFSetupDetailsExtended.init();
    METCustomerMDFSetupDetailsExtended.run();

    /// To refresh the calling form's datasource
    if (METCustomerMDFSetupDetailsExtended && formHasMethod(METCustomerMDFSetupDetailsExtended, identifierStr(metCustomerMdfSetupTable_ds_doRefresh)))
    {
        METCustomerMDFSetupDetailsExtended.metCustomerMdfSetupTable_ds_doRefresh();
    }

    METCustomerMDFSetupDetailsExtended.wait();

    if (METCustomerMDFSetupDetailsExtended.closedOk())
    {
        ret = true;
    }
    else
    {
        this.parmMDFSetupTable(currentRecord);
        ret = false;
    }

    return ret;
}
